package com.yjw.vultr;
import android.widget.*;
import java.util.*;
import org.json.*;
final class ServerScreen {
 final MainActivity a;ServerScreen(MainActivity a){this.a=a;}
 static JSONArray safe(JSONArray all,Manager m)throws Exception{Set<String> own=new HashSet<>();for(int i=0;i<m.records().length();i++)own.add(m.records().getJSONObject(i).optString("id"));List<JSONObject> list=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject raw=all.getJSONObject(i),x=ServerPower.safe(raw);x.put("managed",own.contains(x.optString("id")));list.add(x);}list.sort((x,y)->{int v=Boolean.compare(y.optBoolean("managed"),x.optBoolean("managed"));return v!=0?v:y.optString("date_created").compareTo(x.optString("date_created"));});JSONArray out=new JSONArray();for(JSONObject x:list)out.put(x);return out;}
 void open(){render("");a.loadIfDue("instances",Refresher.INSTANCES,a.manager.data.optLong("home_checked"),()->a.manager.refreshInstances(),this::updated);}
 void updated(){if(a.tab.equals("服务器"))a.renderLater("servers",()->a.manager.data.optLong("home_checked")+"|"+a.manager.data.opt("home_snapshot")+"|"+a.loadErrors.get("instances"),()->render(a.loadErrors.containsKey("instances")?"更新失败，保留上次查询结果；可点刷新重试":""));}
 void actions(){LinearLayout c=a.card("全部服务器","");a.pair(c,"新建服务器",MainActivity.Tone.PRIMARY,()->new StockScreen(a).open(),"更多",()->a.menu("服务器操作",new String[]{"刷新服务器列表","默认方案预览","新建 / 继续已有部署","另外新建一台","本机部署记录"},()->refresh(),()->a.preview(false,false),()->a.preview(true,false),()->a.preview(true,true),()->a.deployments()));}
 void render(String error){int y=a.scroll().getScrollY();a.body.removeAllViews();actions();JSONArray all=a.manager.data.optJSONArray("home_snapshot");long checked=a.manager.data.optLong("home_checked");a.section("服务器 · "+(all==null?0:all.length()),!error.isEmpty()?error:checked==0?(a.loading("instances")?"正在获取…":"等待首次查询"):(HomeState.fresh(checked,System.currentTimeMillis())?"":"缓存 · ")+Core.shortTime(checked)+" 更新"+(a.loading("instances")?" · 更新中…":""));if(all==null||all.length()==0){a.card(checked==0?"正在获取服务器":"暂无服务器","可先预览价格与库存，不会自动创建。");a.restoreScroll(y);return;}for(int i=0;i<all.length();i++){JSONObject x=all.optJSONObject(i);if(x==null)continue;LinearLayout c=a.card(x.optString("label","未命名服务器"),"");boolean fresh=error.isEmpty()&&HomeState.fresh(checked,System.currentTimeMillis()),run=fresh&&HomeState.running(x.optString("status"),x.optString("power_status"));String kind=BootState.kind(x.optString("status"),x.optString("power_status"),x.optString("server_status"),fresh);a.pill(c,(kind.equals("running")?"● ":"")+BootState.label(kind),kind.equals("running")?a.GREEN:BootState.starting(kind)?a.AMBER:a.MUTED);c.addView(a.mono(a.label(x.optString("main_ip")+" · "+x.optString("region").toUpperCase(Locale.ROOT),13,a.INK)));SystemBadge.add(a,c,x);c.addView(a.tnum(a.label("创建于 "+Core.shortTime(x.optString("date_created")),12,a.MUTED)));ServerControls.add(a,c,x,true);}a.restoreScroll(y);}
 void refresh(){a.load("instances",()->a.manager.refreshInstances(),this::updated);if(a.tab.equals("服务器"))render("");}
 void detail(JSONObject x){try{JSONObject r=a.manager.managed(MainActivityId(x));if(r!=null){a.showDeployment(r);return;}}catch(Exception ignored){}a.enterDetail("服务器详情","服务器",()->unmanaged(x));}
 void unmanaged(JSONObject original){JSONObject x;try{x=ServerControls.latest(a.manager,original);}catch(Exception e){x=original;}final JSONObject target=x;LinearLayout c=a.card(x.optString("label","未命名服务器"),"");SystemBadge.add(a,c,x);c.addView(a.mono(a.label(x.optString("main_ip"),13,a.INK)));a.fact(c,"最初创建",Core.time(x.optString("date_created")));a.fact(c,"云端状态",x.optString("status")+" / "+x.optString("power_status"));a.fact(c,"地区 / 套餐",x.optString("region")+" / "+x.optString("plan"));a.fact(c,"规格",x.optString("vcpu_count","—")+" vCPU · "+x.optString("ram","—")+" MB · "+x.optString("disk","—")+" GB");a.fact(c,"实例 ID",x.optString("id"));a.helpCard("订阅凭据","此实例没有本机订阅凭据。请从原部署设备取回链接，不需要为取回链接重装服务器。");ServerControls.add(a,c,target,true);}

 static String MainActivityId(JSONObject x)throws Exception{return Manager.id(x);}
 void more(JSONObject x){a.menu(x.optString("label","服务器操作"),new String[]{"查看部署详情","重装并部署（清空磁盘）","永久删除服务器"},()->detail(x),()->reinstall(x),()->delete(x));}
 void reinstall(JSONObject x){a.confirm("reinstall","将清空："+x.optString("label")+"\n"+x.optString("main_ip")+"\n"+x.optString("id"),()->a.task("提交重装，不自动重试…",()->{JSONObject r=a.manager.reinstall(x);a.ui(()->a.showDeployment(r));}));}
 void delete(JSONObject x){a.confirm("delete","将永久删除："+x.optString("label")+"\n"+x.optString("main_ip")+"\n"+x.optString("id")+"\n独立 IP、快照不随之删除。",()->a.task("提交删除并核对…",()->{a.manager.delete(x);JSONArray all=a.manager.api().list("/instances","instances");a.manager.data.put("home_snapshot",safe(all,a.manager)).put("home_checked",System.currentTimeMillis());a.manager.save();a.ui(()->{a.page("服务器");a.toast("已确认目标实例删除");});}));}
}
